// Delegates entirely to the app's configured Amazon provider (Playwright,
// SerpApi, or mock — selected via AMAZON_PROVIDER, see lib/providers/registry.ts).
// This workflow never needs to know which one actually ran.
const resp = $input.first().json;
if (resp && resp.status === 'SUCCESS' && Array.isArray(resp.products) && resp.products.length > 0) {
  return resp.products.map((p) => ({ json: p }));
}

// Local safety-net only — fires if the app endpoint itself was
// unreachable (the app's own provider chain already falls back to mock
// internally, so this path is rare). Matches lib/providers/amazon/mock.ts.
console.log('APP_AMAZON_PROVIDER_UNREACHABLE_OR_EMPTY');
const ctx = $('Start (called by WF_01)').first().json;
const brand = ctx.brandName;
const marketplace = ctx.marketplace;
const count = 2 + (brand.length % 3);
const out = [];
for (let i = 0; i < count; i++) {
  const asin = 'B0' + brand.replace(/[^A-Z0-9]/gi,'').toUpperCase().padEnd(6,'X').slice(0,6) + i;
  out.push({ json: {
    asin, title: `${brand} Premium Kit ${i+1}`, brandLabel: brand, sellerName: brand, sellerCount: 1,
    price: 19.99 + i * 7.5, currency: 'USD', rating: 4.2, reviewCount: 120 + i * 50,
    url: `https://www.${marketplace}/dp/${asin}`,
    bulletPoints: ['PREMIUM MATERIALS', 'EASY TO USE', `${brand.toUpperCase()} QUALITY`],
    description: `The ${brand} product line built for everyday reliability.`,
    images: [{ url: `https://m.media-amazon.com/images/mock/${asin}-1.jpg`, position: 0, isMain: true }],
  }});
}
return out;
